"""Daemon-only PC7 authority persistence backed by append-only schema v2."""
from __future__ import annotations
import hashlib,json,os
from dataclasses import replace
from pathlib import Path
from typing import Any
import apsw
from .research_db import FailClosed, canonical_json, utc_now
from .conditional_delegation import (OwnerConditionalDelegation,ChildProposal,
    DelegationVerifier)
from .authority_runtime import DaemonContext,FrozenBindings

def _sha(x:Any)->str:return hashlib.sha256(canonical_json(x).encode()).hexdigest()
def _owner_key()->bytes:
    p=os.environ.get('P5_OWNER_ED25519_PUBLIC_KEY_FILE','')
    if not p or not Path(p).is_file():raise FailClosed('OWNER_PUBLIC_KEY_NOT_CONFIGURED')
    b=Path(p).read_bytes()
    if len(b)!=32:raise FailClosed('OWNER_PUBLIC_KEY_INVALID')
    return b
def _owner_uid()->int:return int(os.environ.get('P5_OWNER_PEER_UID','-1'))

class AuthorityStore:
 def __init__(self,db_path:Path):self.db_path=db_path
 def _open(self):
  c=apsw.Connection(str(self.db_path));c.set_busy_timeout(2000);c.execute('PRAGMA foreign_keys=ON');return c
 def proposal(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  b=FrozenBindings(**payload['bindings']).validate();pid=str(payload['proposal_id']);bj=canonical_json(vars(b));now=ctx.recorded_at
  c=self._open()
  try:
   c.execute('BEGIN IMMEDIATE');c.execute('INSERT INTO authority_proposals VALUES(?,?,?,?,?,?,?,?,?)',(pid,b.family_id,b.run_id,b.run_class,b.digest,bj,ctx.session_id,str(payload['expires_at']),now));c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256) VALUES(?,?,?,?,?,?,?,?)",(pid,'NONE','PROPOSED',now,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':'PROPOSED','seq':ctx.ledger_sequence})));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','proposal_id':pid,'state':'PROPOSED','binding_sha256':b.digest}
 def transition(self,pid:str,target:str,ctx:DaemonContext,observed_binding_sha256:str|None=None)->dict[str,Any]:
  c=self._open()
  try:
   row=c.execute('SELECT binding_sha256,producer_session_id,expires_at FROM authority_proposals WHERE proposal_id=?',(pid,)).fetchone()
   if not row:raise FailClosed('PROPOSAL_NOT_FOUND')
   last=c.execute('SELECT transition_id,to_state,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1',(pid,)).fetchone();current=last[1]
   wanted={'PROPOSED':'PRECONDITIONS_PASS','PRECONDITIONS_PASS':'HUMAN_OWNER_SIGNED','HUMAN_OWNER_SIGNED':'APPLIED'}.get(current)
   if target!=wanted:raise FailClosed('ILLEGAL_AUTHORITY_TRANSITION')
   if target=='PRECONDITIONS_PASS' and observed_binding_sha256!=row[0]:raise FailClosed('BINDING_MISMATCH')
   if target in {'HUMAN_OWNER_SIGNED','APPLIED'}:
    if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
    if ctx.session_id==row[1]:raise FailClosed('OWNER_SESSION_SEPARATION_FAILED')
   c.execute('BEGIN IMMEDIATE');c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256) VALUES(?,?,?,?,?,?,?,?)",(pid,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':target,'seq':ctx.ledger_sequence})));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','proposal_id':pid,'state':target}
 def register_delegation(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  d=OwnerConditionalDelegation(**payload);v=DelegationVerifier(_owner_key());v.verify_signature(d);sig=__import__('base64').b64decode(d.owner_signature)
  c=self._open()
  try:c.execute('INSERT INTO owner_conditional_delegations VALUES(?,?,?,?,?,?,?,?,?,?)',(d.delegation_id,d.owner_identity,d.owner_credential_scheme,canonical_json(d.unsigned_payload()),d.owner_signature,hashlib.sha256(sig).hexdigest(),d.owner_session_id,d.expires_at,d.scope_hash,'ACTIVE'))
  finally:c.close()
  return {'status':'PASS','delegation_id':d.delegation_id,'scope_sha256':d.scope_hash}
 def redeem(self,delegation_id:str,proposal_payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  c=self._open()
  try:
   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()
   if not r:raise FailClosed('DELEGATION_NOT_FOUND')
   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);p=ChildProposal(**proposal_payload)
   canonical=c.execute('SELECT producer_session_id,binding_json FROM authority_proposals WHERE proposal_id=?',(p.proposal_id,)).fetchone()
   if not canonical:raise FailClosed('PROPOSAL_NOT_FOUND')
   # Never trust a child payload's producer-session claim. Bind redemption to
   # the daemon-recorded session that created the canonical proposal.
   p=replace(p,producer_session_id=canonical[0])
   binding=json.loads(canonical[1])
   if p.family!=binding['family_id'] or p.run_class!=binding['run_class'] or p.evidence_domain!=binding['evidence_domain'] or p.evaluator_hash!=binding['evaluator_sha256']:raise FailClosed('CANONICAL_PROPOSAL_SCOPE_MISMATCH')
   pre=c.execute("SELECT transition_id,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? AND to_state='PRECONDITIONS_PASS' ORDER BY transition_id DESC LIMIT 1",(p.proposal_id,)).fetchone()
   if not pre:raise FailClosed('PRECONDITIONS_PASS_ABSENT')
   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')
   event=DelegationVerifier(_owner_key()).redeem(d,p,{'to':'PRECONDITIONS_PASS','ledger_sequence':pre[1],'event_id':str(pre[0])},ctx)
   c.execute('BEGIN IMMEDIATE');c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256) VALUES(?,?,?,?,?,?,?,?)",(p.proposal_id,'PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED',ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha(event)));tid=c.last_insert_rowid();c.execute('INSERT INTO delegation_redemptions VALUES(?,?,?,?,?,?)',(event['redemption_event_id'],delegation_id,p.proposal_id,pre[0],tid,event['scope_hash']));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','event':event}
 def revoke(self,delegation_id:str,ctx:DaemonContext)->dict[str,Any]:
  if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
  eid='revoke-'+_sha({'d':delegation_id,'seq':ctx.ledger_sequence})[:32];c=self._open()
  try:c.execute('INSERT INTO owner_delegation_revocations VALUES(?,?,?,?,?)',(eid,delegation_id,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid))
  finally:c.close()
  return {'status':'PASS','event':'OWNER_DELEGATION_REVOKED','revocation_event_id':eid}
 def register_amendment(self,delegation_id:str,amendment_id:str,amendment_hash:str,ctx:DaemonContext)->dict[str,Any]:
  c=self._open()
  try:
   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()
   if not r:raise FailClosed('DELEGATION_NOT_FOUND')
   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')
   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);v=DelegationVerifier(_owner_key());v.verify_signature(d)
   observed=[x[0] for x in c.execute('SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal')]
   expected=['C','A','B']
   if observed!=expected[:len(observed)] or len(observed)>=3 or amendment_id!=expected[len(observed)]:raise FailClosed('C_A_B_ORDER_VIOLATION')
   if amendment_hash not in d.allowed_amendment_hashes:raise FailClosed('AMENDMENT_HASH_OUTSIDE_DELEGATION')
   eid='amend-'+_sha({'d':delegation_id,'a':amendment_id,'seq':ctx.ledger_sequence})[:32]
   c.execute('INSERT INTO amendment_registrations VALUES(?,?,?,?,?,?,?)',(eid,amendment_id,amendment_hash,len(observed)+1,'PREAUTHORIZED_CONDITIONAL_DELEGATION',delegation_id,ctx.recorded_at))
  finally:c.close()
  return {'status':'PASS','amendment_event_id':eid,'amendment_id':amendment_id,'registration_ordinal':len(observed)+1}
